insert into campaigns (id, slug, title, category, location, summary, story, programs, image, image_credit, target, ops_percent, status, organizer, contact, created_at) values
('c-karhutla', 'pulihkan-napas-karhutla', 'Pulihkan napas dan jiwa warga terdampak karhutla', 'Kebakaran hutan', 'Kalimantan Tengah', 'Asap berbulan-bulan meninggalkan sesak di dada dan cemas di kepala. Kita dampingi pemulihannya.', 'Kabut asap kebakaran hutan dan lahan membuat sekolah tutup, warga kehilangan kebun, dan anak-anak tumbuh dengan rasa takut setiap musim kemarau datang. Selain masker dan pemeriksaan kesehatan, kami menghadirkan konselor untuk sesi pemulihan bagi keluarga yang kehilangan mata pencaharian, serta ruang bermain aman bagi anak.', array['Konseling keluarga petani','Ruang aman & trauma healing anak','Masker N95 dan cek kesehatan paru']::text[], '/img/karhutla.jpg', 'Joanne Francis / Unsplash', 250000000, 5, 'aktif', 'Tim dibersamai.id', '', '2026-09-17T03:00:00.000Z'),
('c-banjir', 'trauma-healing-banjir-longsor', 'Trauma healing anak korban banjir dan longsor', 'Banjir & longsor', 'Sumatera Barat', 'Rumah bisa dibangun ulang dalam hitungan bulan. Rasa aman anak-anak butuh pendampingan lebih lama.', 'Banjir bandang dan longsor datang tanpa peringatan. Banyak anak masih terbangun setiap kali hujan deras turun. Bersama psikolog dan relawan lokal, kami menjalankan sesi trauma healing berbasis permainan di posko pengungsian, membekali guru untuk mengenali tanda trauma, dan menyalurkan paket kebutuhan dasar bagi keluarga.', array['Trauma healing berbasis permainan','Pelatihan guru pendamping','Paket pangan dan kebersihan']::text[], '/img/banjir.jpg', 'Saikiran Kesari / Unsplash', 180000000, 5, 'aktif', 'Tim dibersamai.id', '', '2026-09-27T03:00:00.000Z'),
('c-gempa', 'pendampingan-penyintas-gempa', 'Pendampingan psikologis penyintas gempa', 'Gempa bumi', 'Jawa Barat', 'Getaran sudah berhenti, tapi ketakutannya belum. Bantu penyintas pulih lewat konseling dan dukungan kelompok.', 'Setelah gempa, banyak penyintas tidak berani tidur di dalam rumah meski bangunannya sudah dinyatakan aman. Kami membuka sesi konseling individu, kelompok dukungan sebaya untuk para ibu dan lansia, serta menyalurkan kebutuhan dasar selama masa transisi.', array['Konseling individu oleh psikolog','Kelompok dukungan sebaya','Kebutuhan dasar masa transisi']::text[], '/img/gempa.jpg', 'Sebastian Schuster / Unsplash', 200000000, 5, 'aktif', 'Tim dibersamai.id', '', '2026-10-02T03:00:00.000Z'),
('c-demonstrasi', 'pemulihan-mental-pasca-kericuhan', 'Pemulihan mental warga terdampak kericuhan demonstrasi', 'Krisis sosial', 'DKI Jakarta', 'Siapa pun yang terdampak berhak pulih. Kami sediakan konseling gratis tanpa melihat latar belakang.', 'Kericuhan di sekitar aksi demonstrasi meninggalkan luka bagi warga sekitar, pedagang, pelajar, dan relawan medis. Program ini netral dan tidak berpihak: kami menyediakan sesi konseling gratis, layanan pendampingan lewat telepon, dan rujukan ke psikolog bagi siapa pun yang membutuhkan.', array['Konseling gratis tatap muka','Layanan dukungan lewat telepon','Rujukan psikolog & psikiater']::text[], '/img/demonstrasi.jpg', 'Bagir Bahana / Unsplash', 120000000, 5, 'aktif', 'Tim dibersamai.id', '', '2026-10-12T03:00:00.000Z')
